 zone", "type": 2, "isRequired": true, "typeSettings": {"additionalResourceOptions": [], "showDefault": false}, "jsonData": "[{"value": "UTC", "label": "UTC"}, {"value": "Europe/Zurich", "label": "Europe/Zurich"}, {"value": "Europe/Berlin", "label": "Europe/Berlin"}, {"value": "Europe/Paris", "label": "Europe/Paris"}, {"value": "Europe/London", "label": "Europe/London"}, {"value": "America/New_York", "label": "America/New_York"}, {"value": "America/Chicago", "label": "America/Chicago"}, {"value": "America/Los_Angeles", "label": "America/Los_Angeles"}, {"value": "Asia/Singapore", "label": "Asia/Singapore"}, {"value": "Asia/Tokyo", "label": "Asia/Tokyo"}, {"value": "Australia/Sydney", "label": "Australia/Sydney"}]", "value": "UTC", "description": "Used for working hours and the activity pulse"}, {"id": "07d5625d-d714-5aa3-b847-525bf05be1a8", "version": "KqlParameterItem/1.0", "name": "Theme", "label": "Theme", "type": 2, "isRequired": true, "typeSettings": {"additionalResourceOptions": [], "showDefault": false}, "jsonData": "[{"value": "dark", "label": "Dark"}, {"value": "light", "label": "Light"}]", "value": "dark", "description": "Panel colors. Match it to your portal theme (Settings → Appearance)."}], "style": "pills", "queryType": 0, "resourceType": "microsoft.operationalinsights/workspaces"}, "name": "p-global"}, {"type": 1, "content": {"json": "<div style="font-family:Segoe UI,system-ui,sans-serif;padding:8px 14px;border-radius:10px;background:#061A30;border:1px solid #1F4D7A;font-size:12px;color:#8FB0CF;"><b>Privacy mode</b> · users, actors, IP addresses and tenants are pseudonyms</div>"}, "name": "privacy-note", "conditionalVisibilities": [{"parameterName": "Privacy", "comparison": "isEqualTo", "value": "on"}, {"parameterName": "Theme", "comparison": "isNotEqualTo", "value": "light"}]}, {"type": 1, "content": {"json": "<div style="font-family:Segoe UI,system-ui,sans-serif;padding:8px 14px;border-radius:10px;background:#FFFFFF;border:1px solid #D6E1EC;font-size:12px;color:#4F6A86;"><b>Privacy mode</b> · users, actors, IP addresses and tenants are pseudonyms</div>"}, "name": "privacy-note-light", "conditionalVisibilities": [{"parameterName": "Privacy", "comparison": "isEqualTo", "value": "on"}, {"parameterName": "Theme", "comparison": "isEqualTo", "value": "light"}]}, {"type": 11, "content": {"version": "LinkItem/1.0", "style": "tabs", "links": [{"id": "50e925bf-979d-434f-b21d-e4b824273fb6", "cellValue": "Tab", "linkTarget": "parameter", "linkLabel": "Overview", "subTarget": "overview", "style": "link"}, {"id": "d2eedbf0-314a-41f7-bf88-16a109253446", "cellValue": "Tab", "linkTarget": "parameter", "linkLabel": "Identity risk", "subTarget": "risk", "style": "link"}, {"id": "40cdea17-183f-49bb-a5cf-f259a1ffc0b9", "cellValue": "Tab", "linkTarget": "parameter", "linkLabel": "Hunting", "subTarget": "hunt", "style": "link"}, {"id": "f0ede4b6-503b-4f0d-8a86-22e3ca2d46fb", "cellValue": "Tab", "linkTarget": "parameter", "linkLabel": "MFA and access", "subTarget": "access", "style": "link"}, {"id": "16ab5b9f-0c0f-43e2-a0a9-1acb64f7bea8", "cellValue": "Tab", "linkTarget": "parameter", "linkLabel": "Privileged changes", "subTarget": "priv", "style": "link"}, {"id": "dd874a44-9d64-429b-853b-1d011a15969c", "cellValue": "Tab", "linkTarget": "parameter", "linkLabel": "Apps", "subTarget": "apps", "style": "link"}, {"id": "35ca5995-ea38-4ddc-bdb9-778742420faf", "cellValue": "Tab", "linkTarget": "parameter", "linkLabel": "Locations and devices", "subTarget": "geo", "style": "link"}, {"id": "d0752c08-648d-4e4d-b729-7909364c92cd", "cellValue": "Tab", "linkTarget": "parameter", "linkLabel": "Guests", "subTarget": "guests", "style": "link"}, {"id": "d5cb3f76-c546-4218-bc49-040d2e249583", "cellValue": "Tab", "linkTarget": "parameter", "linkLabel": "User lookup", "subTarget": "lookup", "style": "link"}]}, "name": "tabs"}, {"type": 12, "content": {"version": "NotebookGroup/1.0", "groupType": "editable", "items": [{"type": 9, "content": {"version": "KqlParameterItem/1.0", "parameters": [{"id": "d973dfad-b48b-47ec-a277-0f0bcddb0530", "version": "KqlParameterItem/1.0", "name": "OBriefingHtml", "type": 1, "isHiddenWhenLocked": true, "query": "let Priv = "{Privacy}" == "on";
let Salt = "{Workspace}";
let Ps = (v:string, p:string) { iff(Priv and isnotempty(v), strcat(p, "-", substring(hash_sha256(strcat(Salt, "|", v)), 0, 8)), v) };
let Fmt = (n:long) { case(isnull(n), "0", n >= 1000000, strcat(round(n / 1000000.0, 1), "M"), n >= 1000, strcat(round(n / 1000.0, 1), "k"), tostring(n)) };
let s = {TimeRange:start};
let e = {TimeRange:end};
let g = {TimeRange:grain};
let S = SigninLogs
| extend R = tostring(ResultType)
| extend Outcome = case(R == "0", "Success", R in ("50074","50076","50158","50072","50079","50140","50097","50144"), "Interrupted", "Failure")
| extend Country = tostring(LocationDetails.countryOrRegion), City = tostring(LocationDetails.city), OS = tostring(DeviceDetail.operatingSystem), Browser = tostring(DeviceDetail.browser)
| extend Legacy = isnotempty(ClientAppUsed) and ClientAppUsed !in ("Browser", "Mobile Apps and Desktop clients")
| extend SingleFactor = AuthenticationRequirement =~ "singleFactorAuthentication"
| extend RiskyS = RiskLevelDuringSignIn in~ ("low", "medium", "high");
let A = AuditLogs
| extend Actor = coalesce(tostring(InitiatedBy.user.userPrincipalName), tostring(InitiatedBy.app.displayName), "")
| extend ActorIsUser = isnotempty(tostring(InitiatedBy.user.userPrincipalName))
| mv-apply t = TargetResources on (summarize Subject = take_anyif(coalesce(tostring(t.userPrincipalName), tostring(t.displayName)), tostring(t.type) in ("User", "ServicePrincipal", "Application", "Group", "Policy", "Device")), RoleName = take_anyif(tostring(t.displayName), tostring(t.type) == "Role"))
| extend Failed = Result =~ "failure";

let G = S | where TimeGenerated between (s .. e);
let users = toscalar(G | summarize dcount(UserPrincipalName));
let prevUsers = toscalar(S | where TimeGenerated between ((s - (e - s)) .. s) | summarize dcount(UserPrincipalName));
let delta = iff(prevUsers == 0, 0, tolong(round(100.0 * (users - prevUsers) / prevUsers, 0)));
let signins = toscalar(G | count);
let fails = toscalar(G | where Outcome == "Failure" | count);
let failPct = iff(signins == 0, 0, tolong(round(100.0 * fails / signins, 0)));
let sf = toscalar(G | where SingleFactor and Outcome == "Success" | summarize dcount(UserPrincipalName));
let legacy = toscalar(G | where Legacy | count);
let risky = toscalar(G | where RiskyS | summarize dcount(UserPrincipalName));
let countries = toscalar(G | where isnotempty(Country) | summarize dcount(Country));
let roles = toscalar(A | where TimeGenerated between (s .. e) and Category == "RoleManagement" and ActivityDisplayName has_any ("Add member to role", "Add eligible member to role", "Add scoped member to role") | count);
let Anom = G | make-series Actual = count() default = 0 on TimeGenerated from startofday(s) to e step 1d
| extend (Flag, Score, Expected) = series_decompose_anomalies(Actual, 2.5, -1, 'linefit')
| mv-expand TimeGenerated to typeof(datetime), Flag to typeof(int)
| where Flag == 1;
let spikes = toscalar(Anom | count);
let spikeDay = toscalar(Anom | summarize max(TimeGenerated) | project format_datetime(max_TimeGenerated, "yyyy-MM-dd"));
let trend = iff(prevUsers == 0, "no data for the previous period", strcat(iff(delta >= 0, "+", ""), delta, "% active users vs. previous period"));
let body = iff(signins == 0, "No sign-ins in this time range.", strcat('<b style="color:#B5E655;">', Fmt(users), ' users</b> signed in ', Fmt(signins), ' times from ', Fmt(countries), ' countries · ', trend, '<br/>Failure rate <b style="color:#B5E655;">', failPct, '%</b>'));
let chips = strcat(
  strcat('<span style="display:inline-block;margin:10px 8px 0 0;padding:4px 11px;border-radius:20px;font-size:12px;font-weight:600;border:1px solid ', iff(sf > 0, "#F2B700", "#83BA28"), ';color:', iff(sf > 0, "#F2B700", "#83BA28"), ';">', strcat(Fmt(sf), " users signed in with one factor"), '</span>'),
  strcat('<span style="display:inline-block;margin:10px 8px 0 0;padding:4px 11px;border-radius:20px;font-size:12px;font-weight:600;border:1px solid ', iff(legacy > 0, "#FF5C5C", "#83BA28"), ';color:', iff(legacy > 0, "#FF5C5C", "#83BA28"), ';">', strcat(Fmt(legacy), " legacy auth sign-ins"), '</span>'),
  strcat('<span style="display:inline-block;margin:10px 8px 0 0;padding:4px 11px;border-radius:20px;font-size:12px;font-weight:600;border:1px solid ', iff(risky > 0, "#FF5C5C", "#83BA28"), ';color:', iff(risky > 0, "#FF5C5C", "#83BA28"), ';">', strcat(Fmt(risky), " users with risky sign-ins"), '</span>'),
  strcat('<span style="display:inline-block;margin:10px 8px 0 0;padding:4px 11px;border-radius:20px;font-size:12px;font-weight:600;border:1px solid ', iff(roles > 0, "#F2B700", "#83BA28"), ';color:', iff(roles > 0, "#F2B700", "#83BA28"), ';">', strcat(Fmt(roles), " role assignments"), '</span>'));
print Html = strcat('<div style="font-family:Segoe UI,system-ui,sans-serif;padding:14px 20px;border-radius:16px;background:linear-gradient(120deg,#04111F 0%,#082544 100%);border:1px solid #1F4D7A;color:#EAF3FB;"><div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;"><span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:#83BA28;"></span><span style="font-size:11px;letter-spacing:3px;font-weight:700;color:#83BA28;">BRIEFING</span></div>', body, '</div><div>', chips, '</div>')
| extend Html = iff("{Theme}" == "light", replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(replace_string(Html, "#04111F", "#FFFFFF"), "#082544", "#F3F7FB"), "#0A2747", "#F3F7FB"), "#061A30", "#FFFFFF"), "#0A2342", "#FFFFFF"), "#051426", "#F6F9FC"), "#0B2A4A", "#F3F7FB"), "#12324F", "#E4ECF4"), "#1F4D7A", "#D6E1EC"), "#1D4A75", "#D6E1EC"), "#2B5E8C", "#C5D5E6"), "#EAF3FB", "#0E2A47"), "#DCE9F5", "#1D3A57"), "#CFE3F5", "#2A4766"), "#9DB9D3", "#4A6582"), "#8FB0CF", "#4F6A86"), "#7FA3C4", "#56708C"), "#5F82A3", "#5A7189"), "#83BA28", "#4C8A0E"), "#B5E655", "#3F7A0C"), "#F2B700", "#A87600"), "#FF5C5C", "#D93B3B"), "#4FD1FF", "#0B7DB5"), "rgba(31,77,122,0)", "rgba(214,225,236,0)"), Html)", "crossComponentResources": ["{Workspace}"], "queryType": 0, "resourceType": "microsoft.operationalinsights/workspaces", "timeContext": {"durationMs": 20736000000}}]}, "name": "p-obriefinghtml"}, {"type": 1, "content": {"json": "{OBriefingHtml}"}, "name": "o-briefing"}, {"type": 9, "content": {"version": "KqlParameterItem/1.0", "parameters": [{"id": "b69fad02-f996-4c15-9ce2-894475a12f7b", "version": "KqlParameterItem/1.0", "name": "OStepsHtml", "type": 1, "isHiddenWhenLocked": true, "query": "let Priv = "{Privacy}" == "on";
let Salt = "{Workspace}";
let Ps = (v:string, p:string) { iff(Priv and isnotempty(v), strcat(p, "-", substring(hash_sha256(strcat(Salt, "|", v)), 0, 8)), v) };
let Fmt = (n:long) { case(isnull(n), "0", n >= 1000000, strcat(round(n / 1000000.0, 1), "M"), n >= 1000, strcat(round(n / 1000.0, 1), "k"), tostring(n)) };
let s = {TimeRange:start};
let e = {TimeRange:end};
let g = {TimeRange:grain};
let S = SigninLogs
| extend R = tostring(ResultType)
| extend Outcome = case(R == "0", "Success", R in ("50074","50076","50158","50072","50079","50140","50097","50144"), "Interrupted", "Failure")
| extend Country = tostring(LocationDetails.countryOrRegion), City = tostring(LocationDetails.city), OS = tostring(DeviceDetail.operatingSystem), Browser = tostring(DeviceDetail.browser)
| extend Legacy = isnotempty(ClientAppUsed) and ClientAppUsed !in ("Browser", "Mobile Apps and Desktop clients")
| extend SingleFactor = AuthenticationRequirement =~ "singleFactorAuthentication"
| extend RiskyS = RiskLevelDuringSignIn in~ ("low", "medium", "high");
let A = AuditLogs
| extend Actor = coalesce(tostring(InitiatedBy.user.userPrincipalName), tostring(InitiatedBy.app.displayName), "")
| extend ActorIsUser = isnotempty(tostring(InitiatedBy.user.userPrincipalName))
| mv-apply t = TargetResources on (summarize Subject = take_anyif(coalesce(tostring(t.userPrincipalName), tostring(t.displayName)), tostring(t.type) in ("User", "ServicePrincipal", "Application", "Group", "Policy", "Device")), RoleName = take_anyif(tostring(t.displayName), tostring(t.type) == "Role"))
| extend Failed = Result =~ "failure";

let G = S | where TimeGenerated between (s .. e);
let sf = toscalar(G | where SingleFactor and Outcome == "Success" | summarize dcount(UserPrincipalName));
let legacy = toscalar(G | where Legacy | summarize dcount(UserPrincipalName));
let noCA = toscalar(G | where ConditionalAccessStatus =~ "notApplied" and Outcome == "Success" | count);
let spray = toscalar(G | where R in ("50126", "50053", "50057") | summarize U = dcount(UserPrincipalName) by IPAddress, bin(TimeGenerated, 1h) | where U >= 5 | summarize dcount(IPAddress));
let travel = toscalar(G | where Outcome == "Success" and isnotempty(Country) | project TimeGenerated, UserPrincipalName, Country | order by UserPrincipalName asc, TimeGenerated asc | extend pu = prev(UserPrincipalName), pc = prev(Country), pt = prev(TimeGenerated) | where UserPrincipalName == pu and Country != pc and datetime_diff("minute", TimeGenerated, pt) <= 60 | summarize dcount(UserPrincipalName));
let atRisk = toscalar(union isfuzzy=true (datatable(TimeGenerated:datetime, Id:string, RiskState:string)[]), (AADRiskyUsers | project TimeGenerated, Id = tostring(Id), RiskState = tostring(RiskState)) | summarize arg_max(TimeGenerated, *) by Id | where RiskState in~ ("atRisk", "confirmedCompromised") | count);
let creds = toscalar(A | where TimeGenerated between (s .. e) and not(Failed) and ActivityDisplayName has_any ("Add service principal credentials", "Update application – Certificates and secrets management", "Consent to application") | count);
let burst = toscalar(A | where TimeGenerated between (s .. e) and Failed | summarize n = count() by ActivityDisplayName, Actor | where n >= 50 | count);
let Steps = strcat(
  iff(atRisk > 0, strcat('<div style="display:flex;gap:10px;align-items:flex-start;margin-top:8px;"><span style="flex-shrink:0;width:20px;height:20px;border-radius:50%;background:#12324F;border:1px solid #83BA28;color:#B5E655;font-size:11px;font-weight:700;display:inline-flex;align-items:center;justify-content:center;">→</span><span style="font-size:13px;line-height:1.5;color:#DCE9F5;">', strcat("<b>", atRisk, "</b> users are at risk or confirmed compromised in Entra ID Protection. Review under Identity risk."), '</span></div>'), ""),
  iff(spray > 0, strcat('<div style="display:flex;gap:10px;align-items:flex-start;margin-top:8px;"><span style="flex-shrink:0;width:20px;height:20px;border-radius:50%;background:#12324F;border:1px solid #83BA28;color:#B5E655;font-size:11px;font-weight:700;display:inline-flex;align-items:center;justify-content:center;">→</span><span style="font-size:13px;line-height:1.5;color:#DCE9F5;">', strcat("<b>", spray, "</b> source IPs hit five or more accounts within an hour (password spray pattern). See Hunting."), '</span></div>'), ""),
  iff(travel > 0, strcat('<div style="display:flex;gap:10px;align-items:flex-start;margin-top:8px;"><span style="flex-shrink:0;width:20px;height:20px;border-radius:50%;background:#12324F;border:1px solid #83BA28;color:#B5E655;font-size:11px;font-weight:700;display:inline-flex;align-items:center;justify-content:center;">→</span><span style="font-size:13px;line-height:1.5;color:#DCE9F5;">', strcat("<b>", travel, "</b> users signed in from two countries within 60 minutes. See Hunting."), '</span></div>'), ""),
  iff(legacy > 0, strcat('<div style="display:flex;gap:10px;align-items:flex-start;margin-top:8px;"><span style="flex-shrink:0;width:20px;height:20px;border-radius:50%;background:#12324F;border:1px solid #83BA28;color:#B5E655;font-size:11px;font-weight:700;display:inline-flex;align-items:center;justify-content:center;">→</span><span style="font-size:13px;line-height:1.5;color:#DCE9F5;">', strcat("<b>", legacy, "</b> users still use legacy authentication. Block it with Conditional Access."), '</span></div>'), ""),
  iff(sf > 0, strcat('<div style="display:flex;gap:10px;align-items:flex-start;margin-top:8px;"><span style="flex-shrink:0;width:20px;height:20px;border-radius:50%;background:#12324F;border:1px solid #83BA28;color:#B5E655;font-size:11px;font-weight:700;display:inline-flex;align-items:center;justify-content:center;">→</span><span style="font-size:13px;line-height:1.5;color:#DCE9F5;">', strcat("<b>", sf, "</b> users completed a sign-in with a single factor. Require MFA for all users."), '</span></div>'), ""),
  iff(noCA > 0, strcat('<div style="display:flex;gap:10px;align-items:flex-start;margin-top:8px;"><span style="flex-shrink:0;width:20px;height:20px;border-radius:50%;background:#12324F;border:1px solid #83BA28;color:#B5E655;font-size:11px;font-weight:700;display:inline-flex;align-items:center;justify-content:center;">→</span><span style="font-size:13px;line-height:1.5;color:#DCE9F5;">', strcat("<b>", Fmt(noCA), "</b> successful sign-ins were not covered by any Conditional Access policy. See MFA and access."), '</span></div>'), ""),
  iff(creds > 0, strcat('<div style="display:flex;gap:10px;align-items:flex-start;margin-top:8px;"><span style="flex-shrink:0;width:20px;height:20px;border-radius:50%;background:#12324F;border:1px solid #83BA28;color:#B5E655;font-size:11px;font-weight:700;display:inline-flex;align-items:center;justify-content:center;">→</span><span style="font-size:13px;line-height:1.5;color:#DCE9F5;">', strcat("<b>", creds, "</b> app consents or credential changes in this period. Verify them under Apps."), '</span></div>'), ""),
